from pathlib import Path
from html import escape
P=Path(__file__).resolve().parent
(P/'schematics').mkdir(exist_ok=True)
def line(x1,y1,x2,y2):return f'<path d="M{x1},{y1} L{x2},{y2}" stroke="#17394e" stroke-width="5" fill="none"/>'
def text(x,y,s,size=32):return f'<text x="{x}" y="{y}" font-family="Leelawadee UI,Tahoma" font-size="{size}" fill="#153449">{escape(s)}</text>'
def box(x,y,w,h,title):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="12" fill="#edf6fa" stroke="#17394e" stroke-width="4"/>'+text(x+18,y+55,title)
def node(x,y,label):return f'<circle cx="{x}" cy="{y}" r="9" fill="#c8740a"/>'+text(x-30,y-28,label,32)
def gnd(x,y):return line(x,y,x,y+25)+line(x-30,y+25,x+30,y+25)+line(x-20,y+37,x+20,y+37)+line(x-10,y+49,x+10,y+49)
def resistor(x,y,w=120):return line(x,y,x+20,y)+f'<rect x="{x+20}" y="{y-15}" width="{w-40}" height="30" fill="white" stroke="#17394e" stroke-width="4"/>'+line(x+w-20,y,x+w,y)
def cap(x,y,end):return line(x,y,x,y+35)+line(x-28,y+35,x+28,y+35)+line(x-28,y+50,x+28,y+50)+line(x,y+50,x,end)
def note(x,y,w,h,s):return f'<foreignObject x="{x}" y="{y}" width="{w}" height="{h}"><div xmlns="http://www.w3.org/1999/xhtml" lang="th" style="font:34px/1.4 Leelawadee UI,Tahoma;color:#17394e">{s}</div></foreignObject>'
def make(name,title,elements,notes):
 s='<svg xmlns="http://www.w3.org/2000/svg" width="1800" height="1900" viewBox="0 0 1800 1900"><rect width="1800" height="1900" fill="white"/>'
 s+=text(55,90,title,51)+'<rect x="40" y="125" width="1720" height="130" fill="#fff0cf"/>'+note(65,145,1670,100,'<b>วงจรสอนอ่านที่ผู้จัดทำวาดขึ้น — ไม่ใช่วงจรจริงของกล่อง 01–07</b><br/>ตัวเลขเป็นเงื่อนไขตัวอย่าง ห้ามนำไปป้อนไฟหรือตัดสินจุดจริงในภาพ')
 s+=''.join(elements)+note(65,1000,1660,740,notes)
 s+=note(65,1770,1660,90,'สัญลักษณ์เป็นขาหน้าที่ ไม่ใช่เลขขาแพ็กเกจ • ก่อนใช้จริงต้องมี datasheet / pinout / net ที่พิสูจน์แล้ว')+'</svg>'
 f=P/'schematics'/name;f.write_text(s,encoding='utf8');return f

e=[text(70,350,'แหล่งจ่ายตัวอย่าง 12 V'),box(380,410,410,220,'U1 TPS7B8250-Q1'),box(1090,410,410,220,'U2 TLV76733-Q1'),line(100,470,380,470),line(790,470,1090,470),line(1500,470,1690,470),text(395,500,'IN'),text(690,500,'OUT'),text(1110,500,'IN'),text(1400,500,'OUT'),text(520,600,'GND'),text(1220,600,'GND'),node(250,470,'T1'),node(930,470,'T2'),node(1620,470,'T3'),text(205,410,'12 V',36),text(880,410,'5 V nominal',36),text(1510,410,'3.3 V nominal',36),cap(250,470,820),cap(930,470,820),cap(1620,470,820),line(580,630,580,820),line(1290,630,1290,820),line(180,820,1700,820),gnd(580,820),text(650,885,'GND ร่วมในวงจรตัวอย่างเท่านั้น'),text(120,700,'C_IN'),text(810,700,'C_OUT1'),text(1500,700,'C_OUT2')]
make('01_power_ldo.svg','วงจร 01 • อ่านทางจ่ายไฟและเรกูเลเตอร์',e,'<h3>ไล่วัดตามลำดับ T1 → T2 → T3</h3><p>เมื่อแหล่งจ่ายเป็น 12 V และเรกูเลเตอร์เปิดทำงานถูกต้องในข้อกำหนด T2 เป็นเอาต์พุตพิกัด 5 V ของรุ่นย่อยที่ระบุ และ T3 เป็นเอาต์พุตพิกัด 3.3 V ค่าจริงมีความคลาดเคลื่อนตาม datasheet ไม่ใช่เกณฑ์ยอมรับของ ECU ทั้งเจ็ด</p><p><b>สายดำ:</b> GND ที่ยืนยันแล้วของรางนั้น <b>สายแดง:</b> T1/T2/T3 ทีละจุด ภาพย่อไม่ได้แสดง EN และขาควบคุมทั้งหมด ต้องตรวจขาเหล่านี้ด้วยเมื่อ IN มีไฟแต่ OUT ไม่มี</p><p>ถ้า OUT ต่ำ อย่าเปลี่ยน U1/U2 ทันที ต้องแยกโหลดลัดวงจร เงื่อนไข enable กระแสจำกัด ความร้อน และอุปกรณ์กรอง ค่าคาปาซิเตอร์/ความเสถียรต้องใช้เอกสารของรุ่นย่อย ไม่เลือกจากภาพนี้</p><p>แหล่ง: TI TPS7B82-Q1 และ TLV767-Q1 หน้า product/datasheet (ลิงก์ใน README) ไม่ใช่การระบุว่า IC เหล่านี้อยู่ในภาพกล่อง</p>')

e=[text(80,350,'แบบฝึก: V_REF = 5.00 V (สมมติ)'),line(110,450,300,450),resistor(300,450,230),text(340,408,'R1'),line(530,450,650,450),node(650,450,'T_ADC'),line(650,450,650,560),resistor(650,560,180),line(830,560,830,780),gnd(830,780),text(665,630,'R2'),line(650,450,1000,450),resistor(1000,450,180),text(1020,405,'R_SER'),line(1180,450,1510,450),box(1510,390,220,190,'ADC input'),cap(1350,450,780),gnd(1350,780),text(1390,680,'C_FILTER'),text(60,930,'สูตร: V_NODE = V_REF × R2 / (R1 + R2)',43)]
make('02_input_divider.svg','วงจร 02 • ภาครับสัญญาณและตัวกรอง',e,'<h3>ตัวเลขตัวอย่างต้องมาจากเงื่อนไข</h3><p>สมมติ R1 = R2, ไม่มีโหลดดึงกระแสจากจุดแบ่ง และ V_REF = 5.00 V จะได้ T_ADC ก่อน R_SER เท่ากับ <b>2.50 V</b> ในแบบอุดมคติ นี่คือผลคำนวณ ไม่ใช่สเปกเซ็นเซอร์รถจริง</p><p>R_SER กับ C_FILTER ช่วยให้เห็นว่าจุดก่อนและหลังอุปกรณ์อาจตอบสนองต่างกันตามเวลา ต้องแยกแรงดัน DC ออกจากการเปลี่ยนแปลงของสัญญาณ และไม่ตีความ C เป็นทางลัดวงจรจากเสียงบี๊บช่วงชาร์จ</p><p>บนกล่องจริง ให้เริ่มจากขาสัญญาณที่ยืนยันแล้ว ไล่ผ่าน R/อุปกรณ์ป้องกันไปยังขารับ IC และระบุกราวด์สัญญาณ ห้ามถือว่าทุกขาอินพุตควรได้ 2.50 V หรือทุกเซ็นเซอร์ใช้ 5 V</p><p>สัญลักษณ์นี้ไม่แสดง protection/clamp ทุกตัว ไม่ใช่วงจรสำหรับนำไปต่อกับ ADC จริงโดยไม่ตรวจข้อจำกัดอินพุต</p>')

e=[text(75,350,'V_SUPPLY ตัวอย่าง 12 V'),line(180,400,180,470),line(180,470,650,470),'<path d="M650,470 C650,400 705,400 705,470 C705,400 762,400 762,470 C762,400 820,400 820,470 C820,400 880,400 880,470" stroke="#17394e" stroke-width="5" fill="none"/>',text(650,405,'L_LOAD'),line(880,470,1150,470),node(1150,470,'D'),line(1150,470,1150,650),box(970,650,390,170,'Q1 สวิตช์ Low-side'),text(1280,700,'D'),text(985,785,'G'),text(1080,795,'S'),line(1150,820,1150,895),gnd(1150,895),line(970,750,740,750),resistor(560,750,180),text(560,705,'R_GATE'),line(560,750,260,750),text(60,750,'คำสั่ง Gate'),line(520,470,520,305),line(1000,470,1000,305),line(520,305,705,305),line(815,305,1000,305),f'<path d="M705,275 L705,335 M705,305 L815,275 L815,335 Z" fill="white" stroke="#17394e" stroke-width="4"/>',text(550,275,'วงจรคลายพลังงาน: คาโทดหันไป V_SUPPLY',25)]
make('03_low_side.svg','วงจร 03 • ภาคขับโหลดแบบ Low-side',e,'<h3>คำสั่งกับแรงดันเอาต์พุตไม่ใช่สิ่งเดียวกัน</h3><p>ในสวิตช์อุดมคติ เมื่อ Q1 เปิด จุด D เข้าใกล้กราวด์ เมื่อ Q1 ปิดและกระแสโหลดคลายหมดแล้ว จุด D อาจเข้าใกล้ V_SUPPLY หากโหลดยังต่ออยู่ ค่าระหว่างเปลี่ยนสถานะมี transient จึงใช้ตัวเลข DC เดียวแทนไม่ได้</p><p>รูปโหลดเป็นสัญลักษณ์เชิงหน้าที่ ไม่ระบุว่ากล่องใดขับหัวฉีด คอยล์ มอเตอร์ หรือ SCV ภาคขับจริงอาจใช้ clamp/boost/half-bridge ต่างจากภาพนี้</p><p><b>ก่อนวัด:</b> รู้ขา Gate/Drain/Source จาก datasheet และเน็ตจริง ตรวจพิกัด differential/common-mode ของโพรบ ห้ามหนีบกราวด์สโคปแบบต่อ earth ลงจุดสวิตชิ่งโดยไม่รู้ reference</p><p>ผล Gate เปลี่ยนแต่เอาต์พุตไม่เปลี่ยนยังต้องแยกโหลด สายไฟ แหล่งจ่าย วงจรป้องกัน และตัวขับ ไม่ใช่ตัดสิน Q1 เสียทันที</p>')

e=[box(100,390,420,230,'แหล่งสัญญาณตัวอย่าง'),line(520,450,1530,450),node(800,450,'SIGNAL'),line(520,570,1000,570),text(540,625,'S_RETURN'),line(1000,570,1000,750),box(1260,650,410,150,'มิเตอร์ B: 2.70 V'),box(570,700,450,150,'มิเตอร์ A: 2.50 V'),line(800,450,800,700),line(1000,750,1020,750),line(1530,450,1530,650),line(1460,800,1460,920),gnd(1460,920),text(1130,1000,'BODY reference'),text(70,920,'สมมติ S_RETURN สูงกว่า BODY 0.20 V',38)]
make('04_reference_ground.svg','วงจร 04 • วัดเทียบกราวด์ให้ถูกเน็ต',e,'<h3>เลขเดียวกันจะเปลี่ยนเมื่อเปลี่ยนจุดอ้างอิง</h3><p>สมมติสัญญาณจริงเทียบ S_RETURN = 2.50 V และ S_RETURN สูงกว่า BODY = 0.20 V มิเตอร์ A จึงอ่าน 2.50 V ส่วนมิเตอร์ B อ่าน 2.70 V นี่เป็นตัวอย่างคำนวณ ไม่ใช่ค่า sensor return ที่ยอมรับได้บนรถ</p><p>มิเตอร์ทั้งสองเป็นอินพุตความต้านทานสูง เส้นมิเตอร์ไม่ใช่สาย jumper ห้ามพ่วง S_RETURN ลง BODY เพื่อให้เลขเหมือนกัน การเชื่อมกราวด์ผิดอาจเปลี่ยนวงจรหรือทำให้เสียหาย</p><p>ในการไล่กล่องจริง ต้องยืนยันแหล่งอ้างอิงของขานั้นก่อน ใบ 6 และใบ 7 ยังไม่ยืนยัน reference ใดจากภาพ และบางระบบมีวงจรอ้างอิงต่างศักย์ที่ไม่ควรถือเป็นตัวถัง</p><p>ผลอ่านต่างกันต้องตรวจภาวะโหลด ความต่อเนื่อง และแรงดันตกคร่อมตามคู่มือก่อนสรุปสาเหตุ แหล่งหลักการโพรบ: Tektronix ABCs of Probes</p>')

f=P/'output/atlas.html';s=f.read_text(encoding='utf8');marker='<section class="graphic">'
extra=''.join('<section class="graphic"><img class="plate" src="../schematics/'+name+'"/></section>' for name in ['01_power_ldo.svg','02_input_divider.svg','03_low_side.svg','04_reference_ground.svg'])
s=s.replace(marker,extra+marker,1)
references='''<section class="text"><h1>แหล่งอ้างอิงและขอบเขต</h1><h2>ภาพอุปกรณ์</h2><p>ภาพต้นฉบับทั้งหมด 19 ภาพมาจากผู้ใช้ในบทสนทนานี้ สำเนา originals เก็บไฟล์เดิมแบบไม่เปลี่ยนข้อมูลและบันทึก SHA256 ชั้นกำกับอยู่ใน annotated แยกจากไฟล์เดิม</p><h2>วงจรสอน</h2><p>ผังและการคำนวณเป็นภาพวาดของผู้จัดทำ ไม่ใช่ผัง OEM ของกล่อง 01–07 แรงดันตัวอย่างในแผ่นสอนไม่ใช่ค่าผ่านที่ใช้กับกล่องจริง</p><p><a href="https://www.ti.com/product/TPS7B82-Q1">Texas Instruments: TPS7B82-Q1</a> ใช้ยืนยันว่ามีรุ่นเอาต์พุตคงที่ 5 V ในตระกูลที่เลือกสำหรับตัวอย่าง ไม่ใช่การอ่านเบอร์จากบอร์ด</p><p><a href="https://www.ti.com/product/TLV767-Q1">Texas Instruments: TLV767-Q1</a> ใช้ประกอบตัวอย่างการสร้างราง 3.3 V จากไฟเข้าที่เหมาะสม ข้อกำหนดขา enable, capacitor และพิกัดต้องดูเอกสารรุ่นย่อย</p><h2>วิธีวัดและจุดอ้างอิง</h2><p><a href="https://www.fluke.com/en-us/learn/blog/digital-multimeters/how-to-measure-resistance">Fluke: How to Measure Resistance</a> ใช้เป็นหลักวิธีตัดไฟและจัดการพลังงานคงค้างก่อนวัดความต้านทาน ไม่ใช่สเปกความต้านทานของ ECU</p><p><a href="https://www.tek.com/en/documents/whitepaper/abcs-probes-primer">Tektronix: ABCs of Probes</a> ใช้ประกอบความต่างของการวัดเทียบกราวด์และ differential ไม่ใช่พิกัดจุดสวิตชิ่งของกล่องจริง</p><h2>งานที่ยังไม่ยืนยัน</h2><p>หมายเลขอะไหล่/รุ่นของกล่องส่วนใหญ่, มุมมองเลขขาปลั๊ก, เบอร์ IC ชัดทุกตัว, เน็ตผ่านชั้นใน, กราวด์อ้างอิง และค่าแรงดันใช้งานจริง ยังต้องมีข้อมูลเพิ่มหรือผลวัดบนอุปกรณ์ที่ยืนยันแล้ว จึงยังไม่มีผังวงจรจริงครบกล่องใด</p><p>ทีมเอเจนต์เป็นบทบาทตรวจภาพและตรรกะ ไม่ใช่การรับรองจากผู้ผลิตหรือผลทดลองกับฮาร์ดแวร์</p></section>'''
s=s.replace('</body>',references+'</body>');f.write_text(s,encoding='utf8')
print('Added four teaching schematics and references; planned total33 pages')
